import ctypes
import json
import os
import plistlib
import re
import subprocess
import time
from pathlib import Path


CACHE_DIR = Path.home() / "Library" / "Caches" / "com.notchany.agent"
CACHE_FILE = CACHE_DIR / "system-status-v1.json"


FALLBACK_TEXT = {
    "no_battery": "无电池",
    "charging": "充电中",
    "charged": "已充满",
    "on_ac": "接通电源",
    "discharging": "放电中",
    "wifi": "Wi-Fi",
    "ethernet": "有线",
    "vpn": "VPN",
    "offline": "离线",
}


def text(key):
    try:
        return notch_t(key)
    except Exception:
        return FALLBACK_TEXT.get(key, key)


def run(args, timeout=4, binary=False):
    try:
        result = subprocess.run(
            args,
            check=True,
            capture_output=True,
            timeout=timeout,
        )
        return result.stdout if binary else result.stdout.decode("utf-8", "replace")
    except Exception:
        return b"" if binary else ""


def clamp(value, low=0.0, high=100.0):
    return max(low, min(high, value))


def read_cache():
    try:
        return json.loads(CACHE_FILE.read_text("utf-8"))
    except Exception:
        return {}


def write_cache(data):
    try:
        CACHE_DIR.mkdir(parents=True, exist_ok=True)
        temp = CACHE_FILE.with_suffix(".tmp")
        temp.write_text(json.dumps(data, separators=(",", ":")), "utf-8")
        os.replace(temp, CACHE_FILE)
    except Exception:
        pass


def cpu_ticks():
    try:
        lib = ctypes.CDLL("/usr/lib/libSystem.B.dylib")
        lib.mach_host_self.restype = ctypes.c_uint
        lib.host_processor_info.argtypes = [
            ctypes.c_uint,
            ctypes.c_int,
            ctypes.POINTER(ctypes.c_uint),
            ctypes.POINTER(ctypes.POINTER(ctypes.c_int)),
            ctypes.POINTER(ctypes.c_uint),
        ]
        cpu_count = ctypes.c_uint()
        info = ctypes.POINTER(ctypes.c_int)()
        info_count = ctypes.c_uint()
        result = lib.host_processor_info(
            lib.mach_host_self(),
            2,
            ctypes.byref(cpu_count),
            ctypes.byref(info),
            ctypes.byref(info_count),
        )
        if result != 0 or info_count.value < 4:
            return []
        values = [int(info[index]) for index in range(info_count.value)]
        return values[: int(cpu_count.value) * 4]
    except Exception:
        return []


def cpu_percent(previous, current):
    if not previous or len(previous) != len(current):
        return 0.0
    used = 0
    total = 0
    for index in range(0, len(current), 4):
        deltas = [max(0, current[index + part] - previous[index + part]) for part in range(4)]
        used += deltas[0] + deltas[1] + deltas[3]
        total += sum(deltas)
    return clamp(used * 100.0 / total) if total else 0.0


def memory_status():
    total = 0
    try:
        total = int(run(["/usr/sbin/sysctl", "-n", "hw.memsize"]).strip())
    except Exception:
        pass
    pressure = run(["/usr/bin/memory_pressure", "-Q"], timeout=3)
    match = re.search(r"free percentage:\s*(\d+)%", pressure)
    used_percent = 100.0 - float(match.group(1)) if match else 0.0
    used = total * used_percent / 100.0
    return {
        "percent": round(clamp(used_percent), 1),
        "used_bytes": int(used),
        "total_bytes": total,
    }


def battery_status(cache):
    battery = {}
    raw = run(["/usr/sbin/ioreg", "-r", "-c", "AppleSmartBattery", "-a"], binary=True)
    if raw:
        try:
            values = plistlib.loads(raw)
            battery = values[0] if values else {}
        except Exception:
            battery = {}
    if not battery:
        return {
            "present": False,
            "percent": 0,
            "state": text("no_battery"),
            "state_key": "absent",
            "health": None,
            "cycles": None,
            "temperature": None,
        }

    now = time.time()
    health = cache.get("battery_health")
    health_checked = float(cache.get("battery_health_checked", 0))
    if health is None or now - health_checked > 1800:
        profile = run(["/usr/sbin/system_profiler", "SPPowerDataType", "-json"], timeout=6)
        try:
            items = json.loads(profile).get("SPPowerDataType", [])
            for item in items:
                health_info = item.get("sppower_battery_health_info") or {}
                value = health_info.get("sppower_battery_health_maximum_capacity")
                if value:
                    health = int(re.sub(r"\D", "", str(value)))
                    health_checked = now
                    break
        except Exception:
            pass
    if health is None:
        design = float(battery.get("DesignCapacity") or 0)
        maximum = float(battery.get("NominalChargeCapacity") or battery.get("AppleRawMaxCapacity") or 0)
        health = round(clamp(maximum * 100.0 / design)) if design else None

    charging = bool(battery.get("IsCharging"))
    connected = bool(battery.get("ExternalConnected"))
    full = bool(battery.get("FullyCharged"))
    if charging:
        state, state_key = text("charging"), "charging"
    elif full and connected:
        state, state_key = text("charged"), "charged"
    elif connected:
        state, state_key = text("on_ac"), "ac"
    else:
        state, state_key = text("discharging"), "discharging"

    raw_temp = battery.get("Temperature")
    temperature = None
    if isinstance(raw_temp, (int, float)) and raw_temp > 0:
        temperature = round(raw_temp / 10.0 - 273.15, 1)

    return {
        "present": True,
        "percent": int(battery.get("CurrentCapacity") or 0),
        "state": state,
        "state_key": state_key,
        "health": health,
        "health_checked": health_checked,
        "cycles": int(battery.get("CycleCount") or 0),
        "temperature": temperature,
    }


def disk_capacity():
    output = run(["/bin/df", "-k", "/System/Volumes/Data"])
    lines = [line for line in output.splitlines() if line.strip()]
    if len(lines) < 2:
        output = run(["/bin/df", "-k", "/"])
        lines = [line for line in output.splitlines() if line.strip()]
    try:
        parts = lines[-1].split()
        total = int(parts[1]) * 1024
        free = int(parts[3]) * 1024
        used_percent = clamp((total - free) * 100.0 / total) if total else 0.0
        return {"total_bytes": total, "free_bytes": free, "used_percent": round(used_percent, 1)}
    except Exception:
        return {"total_bytes": 0, "free_bytes": 0, "used_percent": 0}


def disk_counters():
    raw = run(["/usr/sbin/ioreg", "-r", "-c", "IOBlockStorageDriver", "-a"], binary=True)
    try:
        entries = plistlib.loads(raw)
        read_bytes = 0
        write_bytes = 0
        for entry in entries:
            stats = entry.get("Statistics") or {}
            read_bytes += int(stats.get("Bytes (Read)") or 0)
            write_bytes += int(stats.get("Bytes (Write)") or 0)
        return {"read": read_bytes, "write": write_bytes}
    except Exception:
        return {"read": 0, "write": 0}


def hardware_ports():
    output = run(["/usr/sbin/networksetup", "-listallhardwareports"])
    wifi = None
    wired = []
    port = ""
    for line in output.splitlines():
        if line.startswith("Hardware Port:"):
            port = line.split(":", 1)[1].strip()
        elif line.startswith("Device:"):
            device = line.split(":", 1)[1].strip()
            if port == "Wi-Fi":
                wifi = device
            elif "Ethernet" in port:
                wired.append(device)
    return wifi, wired


def interface_active(interface):
    if not interface:
        return False
    output = run(["/sbin/ifconfig", interface])
    return "status: active" in output


def default_interface():
    output = run(["/sbin/route", "-n", "get", "default"])
    match = re.search(r"^\s*interface:\s*(\S+)", output, re.MULTILINE)
    return match.group(1) if match else ""


def network_counters(interface):
    if not interface:
        return {"down": 0, "up": 0}
    output = run(["/usr/sbin/netstat", "-ibdn"])
    for line in output.splitlines():
        parts = line.split()
        if len(parts) >= 10 and parts[0] == interface and parts[2].startswith("<Link#"):
            try:
                return {"down": int(parts[6]), "up": int(parts[9])}
            except Exception:
                break
    return {"down": 0, "up": 0}


def delta_rate(previous, current, elapsed, key):
    if elapsed <= 0 or not previous:
        return 0.0
    return max(0.0, (float(current.get(key, 0)) - float(previous.get(key, 0))) / elapsed)


cache = read_cache()
now = time.time()
wifi_device, wired_devices = hardware_ports()
primary_interface = default_interface()
sample = {
    "timestamp": now,
    "cpu": cpu_ticks(),
    "disk": disk_counters(),
    "network": network_counters(primary_interface),
    "interface": primary_interface,
}

previous = cache.get("sample") or {}
elapsed = now - float(previous.get("timestamp", 0))
valid_previous = 0.45 <= elapsed <= 10 and previous.get("interface") == primary_interface
if not valid_previous:
    time.sleep(0.45)
    previous = sample
    now = time.time()
    sample = {
        "timestamp": now,
        "cpu": cpu_ticks(),
        "disk": disk_counters(),
        "network": network_counters(primary_interface),
        "interface": primary_interface,
    }
    elapsed = max(0.001, now - float(previous.get("timestamp", now)))

battery = battery_status(cache)
cpu = cpu_percent(previous.get("cpu"), sample.get("cpu"))
memory = memory_status()
disk = disk_capacity()
disk["read_bps"] = delta_rate(previous.get("disk"), sample["disk"], elapsed, "read")
disk["write_bps"] = delta_rate(previous.get("disk"), sample["disk"], elapsed, "write")

wifi_active = interface_active(wifi_device)
wired_active = any(interface_active(device) for device in wired_devices)
if primary_interface == wifi_device:
    connection = text("wifi")
elif primary_interface in wired_devices:
    connection = text("ethernet")
elif primary_interface.startswith("utun"):
    connection = text("vpn")
elif primary_interface:
    connection = primary_interface
else:
    connection = text("offline")

network = {
    "interface": primary_interface,
    "connection": connection,
    "online": bool(primary_interface),
    "wifi": wifi_active,
    "wired": wired_active,
    "down_bps": delta_rate(previous.get("network"), sample["network"], elapsed, "down"),
    "up_bps": delta_rate(previous.get("network"), sample["network"], elapsed, "up"),
}

cache_out = {
    "sample": sample,
    "battery_health": battery.get("health"),
    "battery_health_checked": battery.get("health_checked", cache.get("battery_health_checked", 0)),
}
write_cache(cache_out)

state = {
    "cpu": {"percent": round(cpu, 1)},
    "memory": memory,
    "battery": battery,
    "disk": disk,
    "network": network,
    "updated_at": int(now * 1000),
}
notch_result(widget=state)

