:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "SF Pro Text", sans-serif;
}
* { box-sizing: border-box; }
html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
  -webkit-user-select: none;
  user-select: none;
}
.panel {
  width: 100%;
  height: 100%;
  padding: 7px 9px 8px;
  border-radius: 13px;
  background: rgba(21, 22, 25, .96);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .12), 0 4px 16px rgba(0, 0, 0, .22);
  color: rgba(255, 255, 255, .94);
  display: grid;
  grid-template-rows: 20px 43px 1fr;
  gap: 4px;
}
svg {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.header, .heading, .metric-title, .detail-head, .detail-label, .rates, .rates span, .links, .links span {
  display: flex;
  align-items: center;
}
.header { justify-content: space-between; min-width: 0; }
.heading { gap: 6px; min-width: 0; font-size: 10.5px; font-weight: 650; }
.brand-icon { width: 13px; height: 13px; color: #7dd3fc; }
.connection {
  max-width: 76px;
  padding: 2px 5px;
  border-radius: 5px;
  background: rgba(125, 211, 252, .12);
  color: #bae6fd;
  font-size: 8.5px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.icon-button {
  width: 21px;
  height: 21px;
  padding: 4px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgba(255, 255, 255, .48);
  cursor: pointer;
}
.icon-button svg { width: 100%; height: 100%; }
.icon-button:hover { background: rgba(255, 255, 255, .10); color: rgba(255, 255, 255, .9); }
.icon-button:active { background: rgba(255, 255, 255, .16); }
.icon-button.busy svg { animation: spin .7s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.quick {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-top: 1px solid rgba(255, 255, 255, .07);
  border-bottom: 1px solid rgba(255, 255, 255, .07);
}
.metric {
  min-width: 0;
  padding: 4px 8px 3px;
  border-right: 1px solid rgba(255, 255, 255, .07);
  position: relative;
}
.metric:first-child { padding-left: 1px; }
.metric.last { border-right: 0; padding-right: 1px; }
.metric-title { gap: 4px; color: rgba(255, 255, 255, .45); font-size: 8.5px; white-space: nowrap; }
.metric-title svg { width: 10px; height: 10px; }
.metric strong {
  display: block;
  margin-top: 2px;
  font: 650 15px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0;
  white-space: nowrap;
}
.metric small {
  display: block;
  margin-top: 2px;
  color: rgba(255, 255, 255, .43);
  font-size: 7.5px;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.track { height: 2px; margin-top: 4px; border-radius: 2px; background: rgba(255, 255, 255, .10); overflow: hidden; }
.track i { display: block; width: 0; height: 100%; border-radius: inherit; background: #7dd3fc; }

.details { display: grid; grid-template-columns: 1fr 1fr; min-height: 0; }
.detail-group { min-width: 0; padding: 2px 9px 0 1px; }
.network-group { padding-left: 10px; padding-right: 1px; border-left: 1px solid rgba(255, 255, 255, .08); }
.detail-head { justify-content: space-between; gap: 6px; min-width: 0; }
.detail-label { gap: 4px; font-size: 8.5px; font-weight: 650; color: rgba(255, 255, 255, .67); }
.detail-label svg { width: 10px; height: 10px; color: #a7f3d0; }
.network-group .detail-label svg { color: #c4b5fd; }
.muted { min-width: 0; font-size: 7.5px; color: rgba(255, 255, 255, .34); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.capacity { display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 7px; margin-top: 3px; }
.capacity strong { font: 600 9px/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: 0; white-space: nowrap; }
.disk-track { margin: 0; }
.disk-track i { background: #a7f3d0; }
.rates { gap: 10px; margin-top: 4px; }
.rates span { min-width: 0; gap: 3px; color: rgba(255, 255, 255, .38); font-size: 7.5px; }
.rates svg { width: 9px; height: 9px; flex: 0 0 auto; }
.rates b { color: rgba(255, 255, 255, .76); font: 560 8.5px/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: 0; white-space: nowrap; }
.down { color: #67e8f9; }
.up { color: #f9a8d4; }
.network-rates { justify-content: space-between; margin-top: 5px; }
.links { gap: 10px; margin-top: 5px; }
.links span { gap: 3px; color: rgba(255, 255, 255, .34); font-size: 7.5px; }
.links em { font-style: normal; }
.links span > i { width: 5px; height: 5px; border-radius: 50%; background: rgba(255, 255, 255, .20); }
.links span.on { color: rgba(255, 255, 255, .72); }
.links span.on > i { background: #34d399; box-shadow: 0 0 5px rgba(52, 211, 153, .55); }
.links svg { width: 9px; height: 9px; }

