const $ = id => document.getElementById(id);
const t = key => (window.__notchWidget.i18n || {})[key] ?? key;

$('title').textContent = t('title');
$('cpuLabel').textContent = t('cpu');
$('memoryLabel').textContent = t('memory');
$('batteryLabel').textContent = t('battery');
$('temperatureLabel').textContent = t('battery_temperature');
$('diskLabel').textContent = t('system_disk');
$('networkLabel').textContent = t('network');
$('wifiLabel').textContent = t('wifi');
$('wiredLabel').textContent = t('ethernet');
$('quick').setAttribute('aria-label', t('core_status'));
$('refresh').title = t('refresh');
$('refresh').setAttribute('aria-label', t('refresh_status'));

function percent(value) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(0, Math.min(100, number)) : 0;
}

function bytes(value, rate = false) {
  const number = Math.max(0, Number(value) || 0);
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let size = number;
  let unit = 0;
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024;
    unit += 1;
  }
  const digits = size >= 100 || unit === 0 ? 0 : size >= 10 ? 1 : 1;
  return size.toFixed(digits) + ' ' + units[unit] + (rate ? '/s' : '');
}

function bar(id, value, warning = false) {
  const amount = percent(value);
  const element = $(id);
  element.style.width = amount + '%';
  element.style.background = warning && amount >= 90 ? '#fb7185' : warning && amount >= 75 ? '#fbbf24' : '';
}

function batteryColor(state) {
  if (state === 'charging') return '#34d399';
  if (state === 'discharging') return '#fbbf24';
  return 'rgba(255,255,255,.94)';
}

function render(result) {
  if (!result || !result.ok || !result.state) return false;
  const state = result.state;
  const cpu = state.cpu || {};
  const memory = state.memory || {};
  const battery = state.battery || {};
  const disk = state.disk || {};
  const network = state.network || {};

  $('cpuValue').textContent = Math.round(percent(cpu.percent)) + '%';
  bar('cpuBar', cpu.percent, true);

  $('memValue').textContent = Math.round(percent(memory.percent)) + '%';
  $('memDetail').textContent = bytes(memory.used_bytes) + ' / ' + bytes(memory.total_bytes);

  if (battery.present) {
    $('batteryValue').textContent = Math.round(percent(battery.percent)) + '%';
    $('batteryValue').style.color = batteryColor(battery.state_key);
    $('batteryDetail').textContent = battery.state + ' · ' + (battery.cycles ?? '--') + ' ' + t('cycles');
    $('tempValue').textContent = battery.temperature == null ? '--°' : Number(battery.temperature).toFixed(1) + '°';
    $('healthDetail').textContent = t('health') + ' ' + (battery.health == null ? '--' : battery.health + '%');
  } else {
    $('batteryValue').textContent = 'N/A';
    $('batteryValue').style.color = 'rgba(255,255,255,.45)';
    $('batteryDetail').textContent = t('battery_not_detected');
    $('tempValue').textContent = '--°';
    $('healthDetail').textContent = t('health') + ' --';
  }

  $('diskFree').textContent = bytes(disk.free_bytes) + ' ' + t('available');
  $('diskTotal').textContent = t('total') + ' ' + bytes(disk.total_bytes);
  $('diskRead').textContent = bytes(disk.read_bps, true);
  $('diskWrite').textContent = bytes(disk.write_bps, true);
  bar('diskBar', disk.used_percent, true);

  $('connection').textContent = network.connection || t('offline');
  $('connection').style.color = network.online ? '#bae6fd' : 'rgba(255,255,255,.42)';
  $('interfaceName').textContent = network.interface || t('no_interface');
  $('netDown').textContent = bytes(network.down_bps, true);
  $('netUp').textContent = bytes(network.up_bps, true);
  $('wifiState').classList.toggle('on', Boolean(network.wifi));
  $('wiredState').classList.toggle('on', Boolean(network.wired));
  return true;
}

async function refresh() {
  const button = $('refresh');
  button.classList.add('busy');
  const result = await notchany.invoke('refresh', null);
  button.classList.remove('busy');
  if (!render(result) && !notchany.state) $('connection').textContent = t('unavailable');
}

$('refresh').addEventListener('click', refresh);
let timer = 0;
notchany.addEventListener('visibilitychange', () => {
  clearInterval(timer);
  timer = 0;
  if (notchany.visible) {
    refresh();
    timer = setInterval(refresh, 3000);
  }
});
notchany.addEventListener('statechange', event => render(event.state));
if (notchany.state) render(notchany.state);
if (notchany.visible) {
  refresh();
  timer = setInterval(refresh, 3000);
}
